   88:     fn retry_set(&self) -> (HashSet<PathBuf>, bool) {
   89:         // cr-fix2-2: the exact set is exact only when every counted
   90:         // failure has a path in it (the unretried remainder is carried
   91:         // separately). A peer that counted failures it could not name
   92:         // (`scan_failures_dropped`) may still send `truncated = false`
   93:         // when its named paths fit; the count exposes the gap, and the
   94:         // set is then inexact — the difference must survive as unretried,
   95:         // never be cleared by a later clean pass.
   96:         let represented = (self.failed_paths.len() as u64).saturating_add(self.unretried);
   97:         let all_represented = self.files_failed <= represented;
   98:         if !self.failed_paths_truncated && !self.failed_paths.is_empty() && all_represented {
   99:             return (self.failed_paths.iter().map(PathBuf::from).collect(), false);
  100:         }
  101:         if !self.failed_paths_truncated && !self.failed_paths.is_empty() {
  102:             return (self.failed_paths.iter().map(PathBuf::from).collect(), true);
  103:         }
  104:         let truncated =
  105:             self.failed_paths_truncated || (self.files_failed as usize) > self.failures.len();
  106:         (
  107:             self.failures
  108:                 .iter()
  109:                 .map(|f| PathBuf::from(&f.relative_path))
  110:                 .collect(),
  111:             truncated,
  112:         )
