  211: /// Outcome of writing payload(s) to a sink.
  212: #[derive(Debug, Default, Clone)]
  213: pub struct SinkOutcome {
  214:     pub files_written: usize,
  215:     pub bytes_written: u64,
  216:     /// Files that failed on their own while the session continued
  217:     /// (D-2026-07-30-1), capped at [`MAX_REPORTED_FILE_FAILURES`].
  218:     pub failures: Vec<FileFailure>,
  219:     /// Every per-file failure counted, including those past the cap.
  220:     pub files_failed_total: u64,
  221:     /// Exact identity of the paths *this outcome's own payload* failed,
  222:     /// uncapped and separate from the reported list (pfc-3). One payload
  223:     /// is inherently bounded — the planner clamps a shard's member count
  224:     /// to at most 4096 (`count_target.clamp(128, 4096)`,
  225:     /// `transfer_plan.rs`), every other payload shape carries exactly one
  226:     /// file — while the reported list is a session-wide report that has
  227:     /// to stay capped for memory and the wire. Keeping identity here is
  228:     /// what lets a shard that failed more members than the cap still
  229:     /// name its healthy ones as complete.
  230:     /// [`SinkOutcome::merge_failures`] deliberately does not extend it:
  231:     /// the session-wide set has no such bound, and the resulting excess
  232:     /// of `files_failed_total` over this list is exactly the signal
  233:     /// [`SinkOutcome::file_failed`] reads as "identity is incomplete
  234:     /// here, answer conservatively".
  235:     failed_paths: std::collections::HashSet<String>,
  236: }
