  238: impl SinkOutcome {
  239:     /// A clean write of `files_written` file(s) carrying `bytes_written`
  240:     /// bytes. Write sites construct through this rather than a struct
  241:     /// literal so later fields do not ripple through every one of them.
  242:     pub fn written(files_written: usize, bytes_written: u64) -> Self {
  243:         Self {
  244:             files_written,
  245:             bytes_written,
  246:             failures: Vec::new(),
  247:             files_failed_total: 0,
  248:             failed_paths: std::collections::HashSet::new(),
  249:         }
  250:     }
