  252:     /// One file that could not be written. Nothing is counted as landed
  253:     /// for it — a failed file is never a written file, whatever partial
  254:     /// bytes reached the destination.
  255:     pub fn failed(relative_path: impl Into<String>, reason: impl Into<String>) -> Self {
  256:         let mut outcome = Self::default();
  257:         outcome.record_failure(relative_path, reason);
  258:         outcome
