  261:     /// Record one per-file failure. The reported list stops growing at
  262:     /// [`MAX_REPORTED_FILE_FAILURES`]; the total keeps counting.
  263:     pub fn record_failure(&mut self, relative_path: impl Into<String>, reason: impl Into<String>) {
  264:         let relative_path = relative_path.into();
  265:         let reason = reason.into();
  266:         // Every contained failure is logged here, exactly once — the one
  267:         // point every recorded failure passes through. A contained file
  268:         // that logs nothing is indistinguishable from a transferred one,
  269:         // and the log is the only surface a failure has until the summary
  270:         // carries the report. `merge`/`merge_failures` copy records rather
  271:         // than re-recording them, so no file is logged twice.
  272:         let named = if relative_path.is_empty() {
  273:             "<destination root>"
  274:         } else {
  275:             relative_path.as_str()
  276:         };
  277:         log::warn!("file failed, session continues: {named} ({reason})");
  278:         self.files_failed_total = self.files_failed_total.saturating_add(1);
  279:         self.failed_paths.insert(relative_path.clone());
  280:         if self.failures.len() < MAX_REPORTED_FILE_FAILURES {
  281:             self.failures.push(FileFailure {
  282:                 relative_path,
  283:                 reason,
  284:             });
  285:         }
  286:     }
